      issues.push('Production environment has development database keys');
    }
    if (env.STRIPE_SECRET_KEY?.startsWith('sk-test-')) {
      issues.push('Production using test Stripe key');
    }
  }

  // Check JWT secret length in production
  if (env.NODE_ENV === 'production' && env.JWT_SECRET) {
    if (env.JWT_SECRET.length < 32) {
      issues.push('JWT secret should be at least 32 characters in production');
    }
  }

  // Database password requirements
  if (env.DATABASE_URL) {
    if (!env.DATABASE_URL.includes('@')) {
      issues.push('Database URL should contain credentials separated by @');
    }
  }

  // Warn about other secrets that shouldn't be in env
  const sensitiveKeys = ['API_KEY', 'PASSWORD', 'SECRET', 'TOKEN'];
  const hasSensitive = Object.keys(env).some(key => 
    sensitiveKeys.some(sensitive => key.includes(sensitive))
  );

  if (hasSensitive) {
    console.warn('⚠️ Warning: Some environment variables contain sensitive keywords');
  }

  if (issues.length > 0) {
    console.error('❌ Security issues found:');
    issues.forEach(issue => console.error(`   - ${issue}`));

    if (failOnError) {
      process.exit(1);
    }
    return false;
  }

  console.log('✅ Environment variable validation passed');
  return true;
};

