      message: 'Missing or invalid Authorization header'
    });
  }

  const token = authHeader.split(' ')[1];
  const decoded = verifyAccessToken(token);

  if (!decoded) {
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'Invalid or expired access token'
    });
  }

  req.user = decoded;
  next();
};

