  // Check if token is revoked (in production: check Redis)
  const revokedToken = refreshTokens.get(normalizeToken(refreshToken));
  if (revokedToken) {
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'Token has been revoked'
    });
  }

  // Generate new tokens
  const { accessToken, refreshToken: newRefreshToken } = generateTokens(decoded.userId);

  // Store refresh token
  if (typeof window !== 'undefined') { // Prevent issues if this runs in browser
    const tokenKey = normalizeToken(refreshToken);
    refreshTokens.set(tokenKey, Date.now());
  }

  res.json({
