const { JSDOM } = require('jsdom');

app.get('/profile', (req, res) => {
  const users = [...]; // from database
  const window = new JSDOM('').window;
  const purify = DOMPurify(window);

  res.send(`
    <h1>Users</h1>
    ${users.map(u => `<div>${purify.sanitize(u.name)}</div>`).join('')}
  `);
});

// Option 2: Escape output
const escapeHtml = (unsafe) => {
  return unsafe
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
};

app.get('/profile', (req, res) => {
  res.render('profile', { 
    users: users.map(u => ({ name: escapeHtml(u.name) })) 
  });
});
```

---

### 4. **No Input Validation**
**OWASP: A02:2021 — Cryptographic Failures**
**Severity:** High

No validation on any inputs (query parameters, request body, response data):

```javascript
app.get('/users', (req, res) => {
  // No validation on req.query
  res.json([{ id: 1, name: 'Alice' }]);
});

app.get('/user-data', (req, res) => {
  // No validation on req.query.userEmail
  // Could be: null, undefined, malicious script, etc.
});
```

**Remediation:**
```javascript
const { body, query, validationResult } = require('express-validator');

app.get('/user-data', 
  [
    query('userId')
      .optional()
      .isInt({ min: 1 })
      .withMessage('User ID must be a positive integer'),
    query('email')
      .optional()
      .isEmail()
      .normalizeEmail()
      .withMessage('Email must be valid'),
    body('password')
      .optional()
      .isLength({ min: 8, max: 128 })
      .matches(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/)
      .withMessage('Password must contain uppercase, lowercase, and number'),
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    res.json({ message: 'Request validated' });
  }
);
```

---

### 5. **No Rate Limiting**
**OWASP: A09:2021 — Security Misconfiguration**
**Severity:** Medium

No protection against brute force, DoS, or credential stuffing attacks:

```javascript
// Attempting to log in with password spray
for (const password of ['password', '123456', 'password123']) {
  await fetch('http://localhost:3000/login', {
    method: 'POST',
    body: JSON.stringify({ email: 'alice@example.com', password })
  });
}
// No rate limiting → easy to brute force
```

**Remediation:**
```javascript
const rateLimit = require('express-rate-limit');

// General API rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per IP
  message: { error: 'Too many requests, try again in 15 minutes' }
});

// More strict for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 5 login attempts per IP
  skipSuccessfulRequests: true, // Don't count successful requests
  skipFailedRequests: false,
  message: { error: 'Too many failed login attempts' }
});

app.use('/api/', limiter); // Apply to all /api/* routes
app.post('/login', authLimiter, (/*...*/) => { /*...*/ });
```

---

### 6. **No HTTPS/Transport Layer Security**
**OWASP: A05:2021 — Security Misconfiguration**
**Severity:** High

Application uses HTTP, allowing credentials to be captured in transit:

```javascript
// Without HTTPS or HSTS, data transmitted in plaintext
app.get('/login', (req, res) => {
  const password = req.body.password; 
  // If attacker uses MITM: they can read password in plain text
});

app.listen(3000, () => {
  // Anyone can sniff: http://attacker.com requests sent to here
  console.log('Server running on port 3000');
});
```

**Remediation:**
```javascript
const https = require('https');
const fs = require('fs');

const options = {
  key: fs.readFileSync('/etc/letsencrypt/live/example.com/privkey.pem'),
  cert: fs.readFileSync('/etc/letsencrypt/live/example.com/fullchain.pem'),
};

// OR require environment variables for prod
const httpsOptions = {
  key: process.env.SSL_KEY_PATH,    // Production servers
  cert: process.env.SSL_CERT_PATH, // Don't hardcode certs!
};

app.listen(httpsOptions ? 443 : 3000, () => {
  console.log('Server running securely');
});
```

**Add HSTS:**
```javascript
const helmet = require('helmet');

app.use(helmet({
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true,
  }
}));

// Use 443 in production
const PORT = process.env.NODE_ENV === 'production' ? 443 : 3000;
```

---

### 7. **No Content Security Policy**
**OWASP: A05:2021 — Security Misconfiguration**
**Severity:** Low-Medium

No CSP headers to prevent XSS attacks:

```javascript
// Without CSP, an attacker can load malicious scripts from any source
// <script src="https://evil.com/malicious.js"></script> would execute
```

**Remediation:**
```javascript
const helmet = require('helmet');

app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"], // For style="..." in HTML
      imgSrc: ["'self'", 'data:', 'https:'],    // Allow images
      connectSrc: ["'self'"],
    }
  }
}));
```

---

### 8. **No Additional Headers (None of OWASP Top 10 Directives)**
**OWASP: A05:2021 — Security Misconfiguration**
**Severity:** Low

Missing security headers:

```javascript
const helmet = require('helmet');

app.use(helmet({
  hsts: true,              // Enforce HTTPS
  noSniff: true,           // Prevent MIME sniffing
  xssFilter: true,         // Add XSS protection header
  referrerPolicy: 'strict-origin-when-cross-origin',
  disablePoweredBy: true   // Hide Express powered-by header
}));
```

---

### 9. **Missing Error Handling**
**OWASP: A05:2021 — Security Misconfiguration**
**Severity:** Medium

No error handling could leak sensitive information:

```javascript
app.get('/db-data', (req, res) => {
  // Unhandled errors reveal stack traces with file paths, DB schema, etc.
  db.query(sqlQuery, params, (err, result) => {
    res.json(result); // Could reveal internal DB structure
  });
});
```

**Remediation:**
```javascript
const winston = require('winston');

const logger = winston.createLogger({
  level: 'info',
  formats: [winston.format.json()]
});

app.use((err, req, res, next) => {
  logger.error('Error occurred', {
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  res.status(500).json({ 
    error: 'Internal server error' 
  });
});

app.get('/db-data', (req, res) => {
  app.use((err, req, res, next) => {
    // Only development should show stack traces
    if (process.env.NODE_ENV === 'development') {
      res.status(500).json({ error: err.message, stack: err.stack });
    } else {
      res.status(500).json({ error: 'Internal server error' });
    }
  });

  db.query(sqlQuery, params, (err, result) => {
    if (err) throw err; // Error handler middleware will catch
    res.json(result);
  });
});
```

---

### 10. **No Request ID Tracking**
**OWASP: A07:2021 — Identification and Authentication Failures**
**Severity:** Low

No way to correlate requests for audit purposes:

```javascript
app.get('/api/data', (req, res) => {
  // Can't trace incident back to specific user once
  // user: { id: 1, email: 'alice@example.com' }
  res.json({ requestId: req.id }); // Add ID
});
```

**Remediation:**
```javascript
const uuid = require('uuid');

app.use((req, res, next) => {
  req.id = uuid.v4();
  res.setHeader('X-Request-ID', req.id);
  next();
});

app.use((err, req, res, next) => {
  res.setHeader('X-Request-ID', req.id);
  logger.error('Error', { reqId: req.id, error: err.message });
  res.status(500).json({ error: 'Internal server error' });
});

app.get('/data', (req, res) => {
  res.json({ 
    requestId: req.id,
    status: 'ok' 
  });
});
```

