# Security Review Report: app.js

**Date**: 2025-06-23
**File**: app.js
**Severity Scale**: 🔴 Critical | 🟠 High | 🟡 Medium | 🟢 Low

---

## Executive Summary

The application is a basic Express.js server with minimal functionality. While the code is simple, several security vulnerabilities exist that should be addressed in any real-world application.

---

## Critical Vulnerabilities

### 1. Missing Authentication (CRITICAL)

**Issue**: No authentication mechanism is in place. The `/users` endpoint is publicly accessible without any authorization checks.

**Impact**: Anyone can access user data, which could contain sensitive information.

**Reference**: OWASP Top 10 - A01:2021 – Broken Access Control

**Recommendation**: Implement authentication and authorization.

```javascript
const express = require('express');
const app = express();
const jwt = require('jsonwebtoken');

// Polyfill for JWT module
const JWT_SECRET = process.env.JWT_SECRET || 'your-secret-key-change-this-in-production';

// Optional: use a proper JWT solution
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access denied. No token provided.' });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token.' });
    }
    req.user = user;
    next();
  });
}

// Protect users endpoint
app.get('/users', authenticateToken, (req, res) => {
  // Keep user data storage separate from API
  const usersDB = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  res.json(usersDB);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

**Also consider**:
- Use environment variables for all secrets: `const JWT_SECRET = process.env.JWT_SECRET;`
- Implement rate limiting
- Use HTTPS only
- Add CORS configuration if this is a public API

---

## High Severity Issues

### 2. Missing Input Validation

**Issue**: No input validation on any endpoints. This could lead to injection attacks or unexpected behavior.

**Impact**: Parameter tampering, injection attacks, DoS potential.

**Reference**: OWASP Top 10 - A03:2021 – Injection

**Recommendation**: Implement schema validation.

```javascript
const express = require('express');
const app = express();

// Use Joi for schema validation
const Joi = require('joi');
const schema = Joi.object({
  status: Joi.string().valid('ok', 'error').required(),
  timestamp: Joi.string().isoDate().optional() // Optional, will be generated
});

app.get('/health', (req, res) => {
  // Validate query parameters if any
  const { error, value } = schema.validate(req.query);
  if (error) {
    return res.status(400).json({ error: 'Invalid request parameters', details: error.details });
  }

  res.json({
    status: 'ok',
    timestamp: new Date().toISOString()
  });
});

// Example of validating route parameters
const userSchema = Joi.object({
  id: Joi.number().integer().positive().required()
});

app.get('/users/:id', (req, res) => {
  // Validate route parameter
  const { error, value } = userSchema.validate({ id: req.params.id });
  if (error) {
    return res.status(400).json({ error: 'Invalid user ID', details: error.details });
  }

  // Find user and return
  res.json({ id: value.id, name: 'Test User', email: 'test@example.com' });
});
```

**Another option - using express-validator**:
```javascript
const { check, validationResult } = require('express-validator');

app.get('/users',
  check('page').isInt({ min: 1 }).withMessage('Page must be a positive integer'),
  check('limit').isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Process request
  }
);
```

---

### 3. Path Traversal Vulnerability (HIGH)

**Issue**: If there were file serving endpoints, proper file path validation would be missing in the current code (though not present in current state).

**Impact**: Remote code execution if file serving is added.

**Reference**: OWASP Top 10 - A05:2021 – Security Misconfiguration (implied)

**Recommendation**: Use a dedicated library and sanitize paths.

```javascript
// For serving static files, use express.static with proper configuration:
app.use(express.static('public', {
  redirect: false,
  dotfiles: 'ignore',
  etag: true,
  extensions: ['htm', 'html', 'js', 'css'],
  setHeaders: (res, pathname) => {
    // Prevent caching of sensitive files
    if (pathname.includes('config') || pathname.includes('secret')) {
      res.setHeader('Cache-Control', 'no-store');
    }
  }
}));

// If serving user-uploaded files:
const fs = require('fs').promises;
const path = require('path');
const userUploadsDir = path.join(__dirname, 'uploads');

app.post('/upload', authenticateToken, async (req, res) => {
  const { filename } = req.body; // In real code, you'd also validate the file

  // Validate filename - prevent path traversal
  if (!filename.match(/^[a-zA-Z0-9_-]+\.(jpg|jpeg|png|gif)$/)) {
    return res.status(400).json({ error: 'Invalid filename' });
  }

  const safePath = path.join(userUploadsDir, filename);
  // Always use path.resolve and check against base directory
  if (!safePath.startsWith(userUploadsDir)) {
    return res.status(403).json({ error: 'Invalid path' });
  }

  // Store file
  await fs.writeFile(safePath, req.body.fileData);
  res.json({ message: 'File uploaded successfully' });
});
```

---

### 4. No Rate Limiting (HIGH)

**Issue**: No rate limiting on any endpoints, making the application vulnerable to brute force attacks and DoS.

**Impact**: Denial of service, credential stuffing.

**Reference**: OWASP Top 10 - A07:2021 – Identification and Authentication Failures

**Recommendation**: Implement rate limiting.

```javascript
const rateLimit = require('express-rate-limit');

// Create rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false,
});

// Apply to all routes (or selectively)
app.use(limiter);

// More specific rate limiting for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 5 attempts per 15 minutes
  message: 'Too many login attempts. Please try again after 15 minutes.',
});

// In a real app, you'd use authLimiter here
```

---

## Medium Severity Issues

### 5. CORS Not Configured (MEDIUM)

**Issue**: CORS is not configured, which could allow malicious websites to make requests to this API.

**Impact**: CSRF attacks potential.

**Reference**: OWASP Top 10 - Related to OWASP A05:2021

**Recommendation**: Configure CORS properly.

```javascript
const cors = require('cors');

const corsOptions = {
  origin: function (origin, callback) {
    // Allow requests with no origin (like mobile apps, curl, postman)
    if (!origin) return callback(null, true);

    const allowedOrigins = [
      'https://your-allowed-domain.com',
      'https://app.yourcompany.com',
    ];

    if (allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  exposedHeaders: ['X-Total-Count'],
  maxAge: 86400, // 24 hours
};

app.use(cors(corsOptions));

// OR in production, use a whitelist approach
app.use(cors({
  origin: process.env.NODE_ENV === 'production'
    ? ['https://your-production-domain.com']
    : true, // Allow in development
  credentials: true
}));
```

---

### 6. Sensitive Information in Logs (MEDIUM)

**Issue**: No sanitization of user data in responses/logs.

**Impact**: Information disclosure in logs.

**Reference**: OWASP Top 10 - A01:2021 – Broken Access Control

**Recommendation**: Sanitize sensitive data before logging.

```javascript
// Example: logging middleware with sanitization
const sanitizeUser = (user) => ({
  id: user.id,
  name: user.name,
  // Don't log email in production
  ...(process.env.NODE_ENV === 'development' ? { email: user.email } : {})
});

app.use('/users', (req, res, next) => {
  const originalJson = res.json.bind(res);

  res.json = function(data) {
    if (Array.isArray(data) && data.length > 0 && data[0].email) {
      const sanitizedData = JSON.parse(JSON.stringify(data).replace(/"email":"[^"]*"/g, '"email":"<redacted>"'));
      return originalJson(sanitizedData);
    }
    return originalJson(data);
  };

  next();
});

// For logging:
const winston = require('winston');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

// Sanitize logs
const formatLogOutput = () => {
  const log = winston.format.printf(
    ({ level, message, timestamp, stack }) => `${timestamp} ${level}: ${stack || message}`
  );
  return format.combine(
    format.timestamp({ format: 'YYYY-MM-DD HH:mm:ss' }),
    printf(log)
  );
};
```

---

### 7. Missing HTTP Headers Security (MEDIUM)

**Issue**: Missing various security headers that provide defense-in-depth protection.

**Impact**: Various attacks mitigated.

**Reference**: OWASP Top 10 - Security Headers Best Practices

**Recommendation**: Add security headers.

```javascript
const helmet = require('helmet');

// Use Helmet to set security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"], // For example only
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", 'data:', 'https:'],
      connectSrc: ["'self'"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true,
  },
  noSniff: true,
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
  xssFilter: true,
}));

// Additional headers if not using helmet
app.use((req, res, next) => {
  // Add authentication challenges for authentication endpoints
  if (req.path.startsWith('/auth') && !req.headers['authorization']) {
    return res.setHeader('WWW-Authenticate', 'Bearer');
  }

  // Add other custom headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');

  next();
});
```

---

### 8. Environment Variable Exposure (MEDIUM)

**Issue**: No validation that required environment variables are set.

**Impact**: Application might run with invalid configurations.

**Reference**: OWASP Top 10 - A05:2021 – Security Misconfiguration

**Recommendation**: Validate environment variables.

```javascript
// Add at the top of app.js
const env = process.env.NODE_ENV || 'development';

// Validate required environment variables
const requiredEnvVars = [
  'PORT',
  'JWT_SECRET', // Change in production
];

const missingEnvVars = requiredEnvVars.filter(
  varName => !process.env[varName]
);

if (missingEnvVars.length > 0) {
  console.error(`ERROR: Missing required environment variables: ${missingEnvVars.join(', ')}`);
  process.exit(1);
}

// Validate and set configuration
const config = {
  port: process.env.PORT || 3000,
  jwtSecret: process.env.JWT_SECRET,
  databaseUrl: process.env.DATABASE_URL,
  secretKey: process.env.SECRET_KEY,
  corsOrigin: process.env.CORS_ORIGIN || '*',
  isDevelopment: env === 'development',
  isProduction: env === 'production',
};

// Validate config in production
if (config.isProduction) {
  if (config.jwtSecret === 'your-secret-key-change-this-in-production') {
    console.error('ERROR: JWT_SECRET is still using the default value!');
    process.exit(1);
  }
}

app.listen(config.port, () => {
  console.log(`Server running on port ${config.port} in ${env} mode`);
});
```

Create a `.env.example` file:
```
PORT=3000
NODE_ENV=development
JWT_SECRET=your-super-secret-jwt-key-here
CORS_ORIGIN=http://localhost:3000
```

---

## Low Severity / Recommendations

### 9. Error Handling

**Issue**: No centralized error handling. Responses may expose stack traces.

**Impact**: Information disclosure.

**Recommendation**: Implement proper error handling.

```javascript
// Central error handler
app.use((err, req, res, next) => {
  console.error(err.stack);

  // Development environment: return stack trace
  if (config.isDevelopment) {
    return res.status(500).json({
      error: 'Internal Server Error',
      message: err.message,
      stack: err.stack,
    });
  }

  // Production: generic error message
  res.status(500).json({
    error: 'Internal Server Error',
    message: 'Something went wrong',
  });
});

// Handle 404 errors
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`,
  });
});
```

---

### 10. SQL Injection Potential (Low - since no DB in current code)

**Issue**: If database queries are added, they should use parameterized queries.

**Reference**: OWASP Top 10 - A03:2021 – Injection (SQL)

**Recommendation**: Use prepared statements.

```javascript
// BAD - SQL Injection risk (if using raw SQL)
const query = `SELECT * FROM users WHERE email = '${req.query.email}'`; // VULNERABLE!

// GOOD - Use parameterized queries or ORM
const User = require('./models/User');

// Using Sequelize (example)
const result = await User.findOne({
  where: { email: req.query.email }
});

// Using Knex
const result = await knex('users')
  .where({ email: req.query.email })
  .first();

// Or Prisma
const user = await prisma.user.findUnique({
  where: { email: req.query.email }
});
```

---

### 11. No Request Body Size Limit

**Issue**: Large request bodies could cause DoS.

**Recommendation**: Set body size limits.

```javascript
// Parse JSON with size limit
app.use(express.json({
  limit: '10mb', // 10 megabyte limit
}));

// Parse URL-encoded data
app.use(express.urlencoded({
  extended: true,
  limit: '10mb',
}));

// Or set limit globally
app.use(express.json({ limit: '100kb' }));
```

