```javascript
// First, install required packages:
// npm install cors helmet express-rate-limit express-validator joi winston

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { validationResult } = require('express-validator');
const logger = require('./config/winston');

// Load environment variables
require('dotenv').config();

// Validate environment variables
const validateEnv = () => {
  const required = ['PORT', 'JWT_SECRET'];
  const missing = required.filter(req => !process.env[req]);
  if (missing.length > 0) {
    throw new Error(`Missing environment variables: ${missing.join(', ')}`);
  }
};

(async () => {
  try {
    validateEnv();
    const app = express();

    // Security middleware
    app.use(helmet());
    app.use(cors());
    app.use(express.json({ limit: '100kb' }));

    // Rate limiting
    const limiter = rateLimit({
      windowMs: 15 * 60 * 1000,
      max: 100,
      message: 'Too many requests'
    });
    app.use(limiter);

    // Logging
    app.use((req, res, next) => {
      logger.info(`${req.method} ${req.path}`, { ip: req.ip, user: req.user?.id });
      next();
    });

    // Routes
    app.get('/health', (req, res) => {
      res.json({ status: 'ok', timestamp: new Date().toISOString() });
    });

    app.get('/users', [
      check('page').optional().isInt({ min: 1 }),
      check('limit').optional().isInt({ min: 1, max: 50 })
    ], validateRequest, authenticateToken, (req, res) => {
      res.json([{ id: 1, name: 'Alice', email: 'alice@example.com' }]);
    });

    // Error handling
    app.use(notFound);
    app.use(errorHandler);

    const PORT = process.env.PORT;
    app.listen(PORT, () => {
      logger.info(`Server running on port ${PORT}`);
    });

  } catch (error) {
    logger.error('Failed to start server', { error: error.message });
    process.exit(1);
  }
})();

function validateRequest(req, res, next) {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
}

function errorHandler(err, req, res, next) {
  logger.error(err.stack);
  res.status(500).json({ error: 'Internal error' });
}

function notFound(req, res, next) {
  res.status(404).json({ error: 'Not found' });
}

// Helper to check authentication
function authenticateToken(req, res, next) {
  // Implementation
  next();
}
