## Recommended Production Approach

### Option 1: AWS Secrets Manager
```javascript
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const AWS_REGION = process.env.AWS_REGION;
const SECRET_NAME = process.env.SECRET_NAME;

const client = new SecretsManagerClient({ region: AWS_REGION });

async function getSecret() {
  const response = await client.send(
    new GetSecretValueCommand({ SecretId: SECRET_NAME })
  );
  return JSON.parse(response.SecretString);
}

module.exports = {
  secrets: await getSecret(),
};
```

### Option 2: HashiCorp Vault
```javascript
const { VaultClient } = require('node-vault');

const vault = new VaultClient({
  endpoint: process.env.VAULT_ADDR,
  token: process.env.VAULT_TOKEN,
});

async function getSecret(path) {
  const secret = await vault.read(path);
  return secret.data.data;
}

module.exports = { vault, getSecret };
```

### Option 3: Docker Secrets
```javascript
const fs = require('fs');
const path = require('path');

function loadDockerSecret(secretName) {
  const filePath = path.join('/run/secrets', secretName);
  if (fs.existsSync(filePath)) {
    return fs.readFileSync(filePath, 'utf8').trim();
  }
  // Fallback to environment variable
  return process.env[secretName];
}

module.exports = { loadDockerSecret };
```

