# Security Review Report: app.js

## Executive Summary
This security review identified **CRITICAL and HIGH severity vulnerabilities** in the application. The code is extremely basic and lacks almost all essential security controls.

---

## 🔴 CRITICAL VULNERABILITIES

### 1. No Authentication or Authorization
**Severity:** CRITICAL
**OWASP Category:** A01:2021 – Broken Access Control

**Problem:** The `/users` endpoint exposes user data to anyone with network access without any authentication.

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Recommendation:**
```javascript
const express = require('express');
const passport = require('passport');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt');

// Configure JWT authentication
app.use(express.json());

// Protect the /users endpoint
app.get('/users', authenticateToken, async (req, res) => {
  try {
    // In production, fetch actual user data
    const users = await User.findAll();
    res.json(users);
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// JWT authentication middleware
function authenticateToken(req, res, next) {
  const token = req.headers['authorization']?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid token' });
    }
    req.user = user;
    next();
  });
}

// Example: Login endpoint
app.post('/login', async (req, res) => {
  try {
    const { email, password } = req.body;

    if (!email || !password) {
      return res.status(400).json({ error: 'Email and password required' });
    }

    const user = await User.findOne({ where: { email } });
    if (!user) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    const isValidPassword = await bcrypt.compare(password, user.password_hash);

    if (!isValidPassword) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    const token = jwt.sign(
      { userId: user.id, email: user.email },
      process.env.JWT_SECRET,
      { expiresIn: '24h' }
    );

    res.json({ token });
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});
```

---

### 2. No Rate Limiting
**Severity:** CRITICAL
**OWASP Category:** A07:2021 – Identification and Authentication Failures

**Problem:** No rate limiting means the application is vulnerable to brute force attacks, DDoS, and credential stuffing.

**Recommendation:**
```javascript
const rateLimit = require('express-rate-limit');

// Global rate limiter
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later' }
});

// Strict rate limiter for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // limit each IP to 5 requests per windowMs
  skipSuccessfulRequests: true,
  message: { error: 'Too many failed attempts' }
});

app.get('/users', generalLimiter, authenticateToken, async (req, res) => { /* ... */ });
app.post('/login', authLimiter, async (req, res) => { /* ... */ });
```

---

## ⚠️ HIGH SEVERITY VULNERABILITIES

### 3. Data Exposure via HTTP (Insecure Transport)
**Severity:** HIGH
**OWASP Category:** A02:2021 – Cryptographic Failures

**Problem:** TLS/SSL is not configured. All data is transmitted in plain text, including potentially sensitive user information.

**Recommendation:**
```javascript
// For production, always use HTTPS
// Configure in your web server (nginx, Apache, etc.) or with Node runtime flags:

// Using environment variables
const HTTPS_PORT = process.env.HTTPS_PORT || 443;

// Server is implicitly not secure - in production, configure TLS:
// Example with node's built-in https module
const https = require('https');
const fs = require('fs');
const options = {
  key: fs.readFileSync('/path/to/private.key'),
  cert: fs.readFileSync('/path/to/certificate.crt')
};

https.createServer(options, app).listen(HTTPS_PORT, () => {
  console.log(`Secure server running on HTTPS port ${HTTPS_PORT}`);
});
```

---

### 4. No CSP (Content Security Policy)
**Severity:** HIGH
**OWASP Category:** A05:2021 – Security Misconfiguration

**Problem:** No XSS protection headers are set.

**Recommendation:**
```javascript
const helmet = require('helmet');

// Use Helmet to set security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
    }
  }
}));
```

---

### 5. No Input Validation
**Severity:** MEDIUM
**OWASP Category:** A03:2021 – Injection

**Problem:** No validation on endpoint parameters - no SQL injection prevention since there's no database query, but still dangerous for future endpoints.

**Recommendation:**
```javascript
// Use a validation library and sanitize inputs
const Joi = require('joi');

// Schema validation
const userSchema = Joi.object({
  name: Joi.string().min(1).max(100).pattern(/^[a-zA-Z\s]+$/).required(),
  email: Joi.string().email().required(),
});

// Apply validation middleware
app.get('/users', authenticateToken, async (req, res) => {
  // Validate query parameters
  const validation = userSchema.validate(req.query);
  if (validation.error) {
    return res.status(400).json({ error: validation.error.details[0].message });
  }

  const users = await User.find({ where: validation.value });
  res.json(users);
});

// For POST requests
app.post('/users', authenticateToken, async (req, res) => {
  const validation = userSchema.validate(req.body);
  if (validation.error) {
    return res.status(400).json({ error: validation.error.details[0].message });
  }

  // Create user with validated, sanitized input
  const user = await User.create(validation.value);
  res.status(201).json(user);
});
```

---

### 6. No Logging or Audit Trail
**Severity:** HIGH
**OWASP Category:** N/A (Best Practice)

**Problem:** No logging of authentication, authorization attempts, or API access.

**Recommendation:**
```javascript
const morgan = require('morgan');

// Add request logging
app.use(morgan('combined', {
  skip: (req, res) => res.statusCode < 400
}));

// Custom logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path}`);

  // Audit log for authentication attempts
  if (req.path === '/login') {
    console.log(`AUTH_ATTEMPT: ${JSON.stringify({
      timestamp: new Date().toISOString(),
      ip: req.ip,
      userAgent: req.get('user-agent'),
      email: req.body?.email,
      success: false
    })}`);
  }

  res.on('finish', () => {
    console.log(`STATUS: ${req.method} ${req.path} ${res.statusCode}`);
  });

  next();
});
```

---

## 🟡 MEDIUM SEVERITY CONCERNS

### 7. No HTTPS Enforcement
**Severity:** MEDIUM
**OWASP Category:** A02:2021 – Cryptographic Failures

**Problem:** Development server recommends running on HTTP, which encourages insecure usage.

**Recommendation:**
```javascript
// Add HTTPS enforcement middleware
const enforceHTTPS = (req, res, next) => {
  if (
    process.env.NODE_ENV === 'production' &&
    !req.secure &&
    req.protocol !== 'https'
  ) {
    return res.redirect(`https://${req.headers.host}${req.originalUrl}`);
  }
  next();
};

app.use(enforceHTTPS);
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

### 8. No CORS Configuration
**Severity:** MEDIUM
**OWASP Category:** A05:2021 – Security Misconfiguration

**Problem:** CORS is not configured - any origin can access the API.

**Recommendation:**
```javascript
const cors = require('cors');

// Configure CORS properly
app.use(cors({
  origin: process.env.CORS_ORIGINS?.split(',') || 'http://localhost:3000',
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));
```

