# Security Review of app.js

## Executive Summary

This application contains **CRITICAL** security vulnerabilities that expose the system to OWASP Top 10 security risks. No authentication, no input validation, and missing security headers make this application highly vulnerable to production use.

---

## Critical Vulnerabilities

### 🔴 CRITICAL 1: No Authentication and Authorization (A01:2021 - Broken Access Control)

**Status:** NOT IMPLEMENTED (All endpoints are completely public)

**Risk Level:** CRITICAL

**Details:** Every route is accessible without any authentication mechanism. Any client making requests to this server can:
- Read user data
- Expose system health status
- Access all endpoints

**Attack Scenario:**
```javascript
// Attacker can make requests without any credentials
curl http://target-server:3000/users       // Returns user data
curl http://target-server:3000/health      // Reveals server availability
```

**Recommendation:**
```javascript
// Approach 1: Implemented Authentication Middleware
const jwt = require('jsonwebtoken');

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// Apply auth middleware to protected routes
app.get('/users', authenticateToken, (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// API keys for stateless authentication
const API_KEYS = process.env.API_KEYS?.split(',') || [];

const requireApiKey = (req, res, next) => {
  const apiKey = req.header('X-API-Key');
  if (!apiKey || !API_KEYS.includes(apiKey)) {
    return res.status(401).json({ error: 'Invalid API key' });
  }
  next();
};

app.get('/users', requireApiKey, (req, res) => {
  res.json([...]);
});

// Environment-based approach
const isDevelopment = process.env.NODE_ENV === 'development';
const requireAuth = isDevelopment ? (req, res, next) => next() : authenticateToken;
// Apply requireAuth middleware
```

---

### 🔴 CRITICAL 2: SQL Injection Vulnerability (A03:2021 - Injection)

**Status:** NOT VULNERABLE YET (but exists due to dynamic string syntax)

**Risk Level:** CRITICAL (if modified later with dynamic queries)

**Details:** The current code doesn't use database queries, but the comment states it's a "Simple application" - if database functionality is added later with unsanitized input, this will be a major vulnerability.

**Recommendation:**
```javascript
// NEVER use string concatenation for queries!
// WRONG:
// db.query(`SELECT * FROM users WHERE id = ${req.params.id}`);

// CORRECT - Use parameterized queries:
const { Pool } = require('pg');
const pool = new Pool({
  host: process.env.DB_HOST,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
  database: process.env.DB_NAME,
});

app.get('/users/:id', async (req, res) => {
  try {
    const result = await pool.query(
      'SELECT * FROM users WHERE id = $1',
      [req.params.id]  // Parameterized - input is not interpreted as code
    );
    res.json(result.rows[0]);
  } catch (error) {
    console.error('Database error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// OR use ORMs (prisma, Sequelize, TypeORM, etc.)
// Example with Prisma:
// const user = await prisma.user.findUnique({
//   where: { id: parseInt(req.params.id) }  // Type-safe filtering
// });
```

---

### 🔴 HIGH 3: Missing Input Validation (A05:2021 - Security Misconfiguration / Broken Access Control)

**Status:** NOT IMPLEMENTED

**Risk Level:** HIGH

**Details:**
- No validation on query parameters
- No validation on request bodies (if added)
- No rate limiting
- Exposes full list of users sensitive information

**Recommendation:**
```javascript
// 1. Use Joi or Zod for input validation
const Joi = require('joi');

const userIdSchema = Joi.object({
  id: Joi.number().integer().positive().required()
});

// Middleware for validation
const validate = (schema) => (req, res, next) => {
  const { error } = schema.validate(req.params);
  if (error) {
    return res.status(400).json({ error: error.details[0].message });
  }
  next();
};

// 2. Apply validation middleware
app.get('/users/:id', validate(userIdSchema), (req, res) => {
  // req.params.id is now guaranteed to be a valid positive integer
  res.json({ id: req.params.id });
});

// 3. Rate limiting to prevent brute force attacks
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,  // 15 minutes
  max: 100,  // Maximum 100 requests per window
  message: { error: 'Too many requests, please try again later' },
  standardHeaders: true,
  legacyHeaders: false,
});

app.use('/api', limiter);

// 4. Input sanitization for user-provided data
const helmet = require('helmet');

// Enable all security headers
app.use(helmet({
  contentSecurityPolicy: false,  // Adjust based on your needs
  crossOriginEmbedderPolicy: false,
  crossOriginOpenerPolicy: false,
}));

// 5. Sanitize output (prevent XSS)
const sanitizeHTML = (str) => {
  const div = document.createElement('div');
  div.textContent = str;
  return div.innerHTML;
};

app.get('/users', (req, res) => {
  const sanitizedUsers = users.map(user => ({
    ...user,
    name: sanitizeHTML(user.name),
    email: sanitizeHTML(user.email)
  }));
  res.json(sanitizedUsers);
});
```

---

### 🟡 MEDIUM 4: Information Disclosure (A02:2021 - Cryptographic Failures)

**Status:** VULNERABLE

**Risk Level:** MEDIUM

**Details:**
- Health endpoint reveals server availability and timestamp
- No CORS restrictions (potential for data theft from unauthorized domains)
- Sensitive health information may leak in production

**Recommendation:**
```javascript
// 1. Restrict health endpoint access in production
app.get('/health', (req, res) => {
  // Only allow localhost and monitoring services
  const allowedOrigins = process.env.ALLOWED_AUDITS?.split(',') || [];
  const origin = req.headers.origin;

  if (process.env.NODE_ENV === 'production' && origin &&
      !allowedOrigins.includes(origin) && origin !== 'http://localhost:3000') {
    return res.status(403).json({ error: 'Forbidden' });
  }

  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development',
    uptime: process.uptime()
  });
});

// 2. Implement CORS configuration
const cors = require('cors');

const corsOptions = {
  origin: (origin, callback) => {
    // Allow requests with no origin (like mobile apps, curl)
    if (!origin) return callback(null, true);

    const allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || [
      'http://localhost:3000',
      'https://yourdomain.com'
    ];

    if (allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      console.error(`Origin ${origin} blocked by CORS`);
      callback(new Error('CORS block'));
    }
  },
  credentials: true,  // Allow cookies if needed
  allowedHeaders: ['Content-Type', 'Authorization'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
};

app.use(cors(corsOptions));

// OR strict CORS for production
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || [],
  credentials: true
}));
```

---

### 🟡 MEDIUM 5: Lack of HTTPS/SSL Enforcement (A02:2021 - Cryptographic Failures)

**Status:** NOT IMPLEMENTED

**Risk Level:** MEDIUM

**Details:**
- Server runs over HTTP (not HTTPS)
- Sensitive data transmitted in plaintext
- vulnerable to Man-in-the-Middle (MITM) attacks

**Recommendation:**
```bash
# Install HTTPS dependencies
npm install express-force-ssl

# Usage with sslify
const sslRedirect = require('express-force-ssl');

app.use(sslRedirect({
  assumeProtocolFromHeaders: true,  // Works with CDN
  trustProxy: false
}));

# OR using SSL module to redirect HTTP to HTTPS
function setupHttpsServer() {
  const https = require('https');
  const fs = require('fs');

  const httpsOptions = {
    key: fs.readFileSync(process.env.SSL_KEY_PATH),
    cert: fs.readFileSync(process.env.SSL_CERT_PATH)
  };

  const server = https.createServer(httpsOptions, app);

  server.listen(443, () => {
    console.log('HTTPS server running on port 443');
  });
}

// Create HTTP server that redirects to HTTPS on port 80
const http = require('http');
const httpServer = http.createServer((req, res) => {
  res.writeHead(301, {
    Location: `https://${req.headers.host}${req.url}`
  });
  res.end();
});

httpServer.listen(80, () => {
  console.log('HTTP server redirecting to HTTPS on port 80');
});
```

---

### 🟡 MEDIUM 6: Missing Security Headers (A05:2021 - Security Misconfiguration)

**Status:** ADMIN DISABLED (helmet() not set)

**Risk Level:** MEDIUM

**Details:**
- No Content Security Policy (CSP)
- No X-Content-Type-Options
- No frame-ancestors (Clickjacking protection)
- No Referrer-Policy

**Recommendation:**
```javascript
const helmet = require('helmet');

// Secure defaults - overrides all these headers:
app.use(helmet());

// If you need custom CSP (required for modern apps)
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'", "'unsafe-inline'", "'unsafe-eval'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    fontSrc: ["'self'"],
    imgSrc: ["'self'", 'data:', 'https:'],
    connectSrc: ["'self'"],
