### 2. ❌ No Input Validation & Sanitization (OWASP A01:2021 - Broken Access Control)

**Severity:** CRITICAL
**Risk:** Malicious input can cause application errors, crashes, or unexpected behavior.

**Finding:** No validation for:
- URL parameters
- Request body data
- Query parameters

**Current Code:**
```javascript
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});
```

**Recommended Solution:** Implement input validation middleware

```javascript
const { body, param, query, validationResult } = require('express-validator');

// Validation middleware
function validateRequest(req, res, next) {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
}

// Parameter validators
const validateUserId = [
  param('id').isInt({ min: 1, max: 10000 }).withMessage('Invalid user ID'),
  validateRequest
];

// Query parameter validators
const validateQuery = [
  query('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  validateRequest
];

// Body validators (for POST/PUT requests)
const validateUserCreation = [
  body('name')
    .notEmpty().withMessage('Name is required')
    .trim().escape()
    .isLength({ min: 2, max: 50 }).withMessage('Name must be 2-50 characters'),
  body('email')
    .notEmpty().withMessage('Email is required')
    .isEmail().normalizeEmail().withMessage('Invalid email format'),
  body('password')
    .notEmpty().withMessage('Password is required')
    .isLength({ min: 8 }).withMessage('Password must be at least 8 characters')
    .matches(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/).withMessage('Password must contain uppercase, lowercase, and number'),
  validateRequest
];

// Apply validation to routes
app.get('/users/:id', validateUserId, (req, res) => {
  const userId = parseInt(req.params.id);
  // User lookup logic
});

app.get('/users', validateQuery, (req, res) => {
