  const limit = parseInt(req.query.limit) || 10;
  // Pagination logic
});

app.post('/users', validateUserCreation, (req, res) => {
  // Create user logic
});
```

---

### 3. ⚠️ Missing Authorization Checks (OWASP A02:2021 - Cryptographic Failures)

**Severity:** HIGH
**Risk:** Endpoints lack proper authorization to determine who can perform actions.

**Finding:** No role-based access control (RBAC) implemented.

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  // Anyone can access all users
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Recommended Solution:** Implement role-based access control

```javascript
// User roles
const ROLES = {
  ADMIN: 'admin',
  USER: 'user',
  GUEST: 'guest'
};

// Authorization middleware
function requireRole(roles) {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Authentication required' });
    }

    if (!roles.includes(req.user.role)) {
      return res.status(403).json({
        error: `Permission denied. Required roles: ${roles.join(', ')}`
      });
    }

    next();
  };
}

// Public endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint - requires authentication
app.get('/users',
  authenticateToken,
  (req, res) => {
    // Only authenticated users can see other users
    // Consider returning only their own data or filtered list
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  }
);

// Current user endpoint - any authenticated user
app.get('/me',
  authenticateToken,
  (req, res) => {
    res.json({
      id: req.user.userId,
      name: 'Alice', // Would come from database
      email: 'alice@example.com'
    });
  }
);

// Admin endpoint
app.delete('/users/:id',
  authenticateToken,
  requireRole([ROLES.ADMIN]),
  validateUserId,
  async (req, res) => {
    // Only admins can delete users
    const userId = parseInt(req.params.id);
    // Delete user logic
    res.json({ message: 'User deleted successfully' });
  }
);
```

