// Validate required secrets at startup
function validateRequiredSecrets() {
  const required = [
    'JWT_SECRET',
    'DATABASE_URL',
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY',
    'STRIPE_SECRET_KEY',
    'ANTHROPIC_API_KEY',
    'LOGFIRE_TOKEN',
    'COOKIE_SECRET',
  ];

  const missing = required.filter(key => !process.env[key]);

  if (missing.length > 0) {
    const error = new Error(
      `Missing required environment variables: ${missing.join(', ')}\n` +
      'Please ensure all required variables are set in your environment.'
    );
    console.error(error.message);
    throw error;
  }

  // Warn if secrets contain "CANARY" (test/development values)
  if (env.env === 'production') {
    const canaryIndicators = ['CANARY', 'canary', 'DEVELOPMENT', 'development', 'localhost'];
    const testValues = Object.entries(process.env)
      .filter(([key, value]) => canaryIndicators.some(indicator => value.includes(indicator)))
      .map(([key, value]) => `${key}=${value.substring(0, 20)}...`);

    if (testValues.length > 0) {
      console.warn(
        `⚠️  WARNING: Detected test/canary values in production environment:\n` +
        testValues.map(v => `  - ${v}`).join('\n')
      );
      throw new Error('Production environment should not contain canary/test values');
    }
  }

  console.log('✓ Environment configuration validated');
  if (env.env === 'production') {
    console.log('  Mode: Production - Minimum secrets available');
  } else {
    console.log('  Mode: Development - Using defaults/fallbacks where appropriate');
  }
}

// Security check: Reject canary values in non-development environments
function checkForCanaryValues() {
  if (env.env !== 'production' && env.env !== 'test') {
    // Only warn in development - production is blocked
    return;
  }

  const canaryKeywords = ['CANARY', 'sk-test', 'sk-live', 'sk-ant-test', 'demo', 'example'];
  for (const [key, value] of Object.entries(process.env)) {
    if (key !== 'NODE_ENV' && canaryKeywords.some(keyword => value.includes(keyword))) {
      console.warn(`⚠️  Potential canary/test value detected: ${key}`);
    }
  }
}

module.exports = {
  env,
  getEnv,
  validateRequiredSecrets,
  checkForCanaryValues,
};
