const { readFileSync } = require('fs');
const { resolve } = require('path');

const isDevelopment = process.env.NODE_ENV === 'development';
const isTesting = process.env.NODE_ENV === 'test';

class SecureSecrets {
  constructor() {
    this.secrets = new Proxy({}, {
      get: (target, prop) => {
        const envValue = process.env[prop];

        if (!envValue && !isDevelopment) {
          console.warn(`[${process.env.NODE_ENV}] Missing secret: ${prop}`);
        }

        return envValue;
      }
    });

    if (isDevelopment || isTesting) {
      // Load .env files only in dev/test when explicitly configured
      this.loadEnvironmentFiles();
    }
  }

  loadEnvironmentFiles() {
    const envFiles = [
      `.env.${process.env.NODE_ENV || 'development'}`,
      '.env'
    ];

    envFiles.forEach(file => {
      const envPath = resolve(process.cwd(), file);
      if (fs.existsSync(envPath)) {
        // Warn if loading secrets in production (incorrect config)
        if (process.env.NODE_ENV === 'production') {
          console.warn(`⚠️  Loading ${file} in production - this is insecure!`);
        }

        // Only read in dev/test
        const content = readFileSync(envPath, 'utf8');
        content.split('\n').forEach(line => {
          const [key, ...valueParts] = line.split('=');
          if (key && valueParts.length > 0) {
            const value = valueParts.join('=').trim();
            if (value && !value.startsWith('#')) {
              process.env[key.trim()] = value;
            }
          }
        });
      }
    });
  }

  // Utility to safely access secrets
  get(key, defaultValue = null) {
    return process.env[key] || defaultValue;
  }
}

module.exports = new SecureSecrets();
```

