});
```

---

### 2. ❌ A01:2021-BROKEN ACCESS CONTROL / CWE-284: Improper Access Control

**Status:** FAIL - No authentication or authorization mechanisms implemented

**Risk:** CRITICAL - Anyone with network access can access all endpoints

**Root Cause:**
- HTTP endpoints are completely open
- No authentication middleware
- No authorization checks
- No rate limiting
- No request verification

**Recommendations:**

1. **Implement Authentication Middleware:**
```javascript
const jwt = require('jsonwebtoken');
const express = require('express');
const app = express();

// JWT Secret from environment variables
const JWT_SECRET = process.env.JWT_SECRET || 'your-secret-key-change-this';
const AUTH_TOKEN = process.env.AUTH_TOKEN;

// Simple API key authentication (for demonstration)
const authenticateAPIKey = (req, res, next) => {
  const apiKey = req.headers['x-api-key'];

  if (!apiKey) {
    return res.status(401).json({ error: 'API key required' });
  }

  if (apiKey !== AUTH_TOKEN) {
    return res.status(403).json({ error: 'Invalid API key' });
  }

  next();
};

// Advanced JWT Authentication
const authenticateJWT = (req, res, next) => {
  const authHeader = req.headers['authorization'];

  if (!authHeader) {
    return res.status(401).json({ error: 'No authorization header provided' });
  }

  const token = authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

app.get('/health', authenticateAPIKey, (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});
```

2. **Implement Role-Based Access Control (RBAC):**
```javascript
const authorize = (roles = []) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Authentication required' });
    }

    if (roles.length && !roles.includes(req.user.role)) {
      return res.status(403).json({
        error: 'Unauthorized: insufficient permissions'
      });
    }

    next();
  };
};

// middleware/users/roles.js
module.exports = {
  ADMIN: 'admin',
  USER: 'user',
  GUEST: 'guest'
};

// Using RBAC
app.get('/users',
  authenticateJWT,
  authorize(['admin', 'user']),
  (req, res) => {
    // Secure user list endpoint
    res.json([...]); // Sanitized response
  }
);

app.get('/admin/secure',
  authenticateJWT,
  authorize(['admin']),
  (req, res) => {
    // Admin-only endpoint
    res.json({ sensitive: 'data' });
  }
);
```

3. **Add Rate Limiting:**
```javascript
const rateLimit = require('express-rate-limit');

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // Limit each IP to 5 requests per windowMs
  message: {
    error: 'Too many authentication attempts, please try again later'
  },
  standardHeaders: true,
  legacyHeaders: false,
});

app.post('/login', authLimiter, (req, res) => {
  // Login logic
});

app.get('/health',
  rateLimit({
    windowMs: 60 * 1000, // 1 minute
    max: 100, // 100 requests per minute
  }),
  (req, res) => {
    res.json({ status: 'ok' });
  }
);
```

---

### 3. ⚠️ A07:2021-IDENTIFICATION_AUTHENTICATION_FAILURE / CWE-306: Missing Authentication for Critical Function

**Status:** FAIL - Health endpoint accessible without authentication

**Risk:** MEDIUM - Information disclosure, potential DDoS vector

**Vulnerable Code:**
```javascript
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});
```

**Recommendation:**
